                <strong>Order ID:</strong> {order.id}
              </p>
              <p className="text-gray-700 mb-2">
                <strong>Order Date:</strong> {format(new Date(order.orderDate), 'PPP p')}
              </p>
              <p className="text-gray-700 mb-2">
                <strong>Total Amount:</strong> ₹{order.totalAmount.toFixed(2)}
              </p>
              <p className="text-gray-700 mb-2">
